sysauto_script.script:
(function() {
    var groupIds = [
        '7b16d1981bb8b5108d594047bc4bcb45', //CECCE - Equipe Triage
        '95aa1d7c1bb10a508d594047bc4bcb43', //CECCE - Direction du SSA-ES
        'e7b604994763661083857acc416d4349', //CECCE - Orthophonistes - Admin
        'b678afa31ba48e50d991c882604bcb1b', //CECCE - Orthophonistes - comité ROI
        '699f42af1beb2510d991c882604bcb05', //CECCE - Orthophonistes
        '383751b81bb10a508d594047bc4bcb87', //CECCE - Orthophonistes du régulier
        '2bb8513c1bb10a508d594047bc4bcbc3', //CECCE - Orthophonistes du volet TSA/CS
        'a099d53c1bb10a508d594047bc4bcbe6', //CECCE - Éducatrices ressources langage
        'c01a9d3c1bb10a508d594047bc4bcbe1', //CECCE - Éducatrices ressources langage TSA/CS
        '6829553c1bb10a508d594047bc4bcbd9', //CECCE - Éducatrices ressources langage - comité SLI
        '8bf880d94763661083857acc416d4316', //CECCE - Éducatrices ressources langage TSA/CS - Comité SCS
    ];

    groupIds.forEach(function(grpId) {
        var members = [];
        var gm = new GlideRecord('sys_user_grmember');
        gm.addQuery('group', grpId);
        gm.query();
        while (gm.next()) {
            members.push(gm.user.toString());
        }

        var description = '';
        var group = new GlideRecord('sys_user_group');
        group.get(grpId);
        description = group.description;
        gs.info('desc :' + description);

        var rec = new GlideRecord('x_ndecd_triage_2_0_r_le_orthophonie');
        rec.addQuery('group', grpId);
        rec.query();
        if (rec.next()) {
            rec.setValue('membres', members.join(','));
            rec.setValue('description', description);
            rec.update();
        } else {
            rec.initialize();
            rec.setValue('group', grpId);
            rec.setValue('description', description);
            rec.setValue('membres', members.join(','));
            rec.insert();
        }
    });
})();
